from __future__ import annotations

from fastapi.responses import HTMLResponse

from app.build_info import APP_VERSION, BUILD_ID


def hunting_page() -> HTMLResponse:
    html = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>NCT · Hunt</title>
<style>
:root{color-scheme:dark;--bg:#08131b;--panel:#101d26;--line:#294553;--text:#edf6fb;--muted:#9eb0b8;--accent:#57d6bf;--blue:#73bfff;--good:#61d095;--warn:#f4c95d;--bad:#ff7b7b;--hunt-header-offset:132px}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top right,#102b35,#08131b 48%);color:var(--text);font:14px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}header,main{max-width:1280px;margin:auto}header{position:sticky;top:0;z-index:100;padding:16px 0 14px;border-bottom:1px solid var(--line);background:rgba(8,19,27,.97);backdrop-filter:blur(14px)}h1{margin:0 0 4px;font-size:26px}h2{margin:0 0 8px;font-size:19px}h3{margin:17px 0 8px;font-size:15px}.eyebrow{color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.sub,.hint,.meta,.empty{color:var(--muted)}.sub{margin:0}.nav,.actions,.source-links,.chips{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.nav{margin-top:12px}.nav a,.source-links a{border:1px solid #315264;background:#142d38;color:#b9cadc;border-radius:7px;padding:9px 13px;text-decoration:none;font-weight:700}.nav a.active{background:var(--accent);border-color:var(--accent);color:#07171b}main{padding:24px 0 60px}.panel{background:rgba(16,29,38,.96);border:1px solid var(--line);border-radius:12px;padding:18px;margin-bottom:18px;box-shadow:0 10px 35px #0003}.evidence-guide{position:sticky;top:var(--hunt-header-offset);z-index:80;max-height:calc(100vh - var(--hunt-header-offset) - 12px);overflow:auto;background:rgba(16,29,38,.985);box-shadow:0 14px 40px #0008}.overview{display:flex;justify-content:space-between;gap:18px;align-items:center}.overview p{margin:3px 0}.picker{display:grid;grid-template-columns:1.5fr 1.5fr auto auto;gap:10px;align-items:end}.filters{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;align-items:end;margin:14px 0}.checkbox{display:flex;align-items:center;gap:7px;min-height:42px}.checkbox input{width:auto}label{display:block;color:#bed0da;font-size:12px;font-weight:700;margin:4px 0 5px}select,input{width:100%;background:#0b1520;color:var(--text);border:1px solid #365268;border-radius:8px;padding:10px 11px;font:inherit}button{border:1px solid #3b6f91;background:#174665;color:#fff;border-radius:7px;padding:10px 14px;font:inherit;font-weight:750;cursor:pointer}button.secondary{background:transparent;border-color:#49617d}button:disabled{opacity:.5;cursor:not-allowed}.status{min-height:22px;margin-top:10px;color:var(--muted)}.status.good{color:var(--good)}.status.warn{color:var(--warn)}.status.bad{color:var(--bad)}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:9px;margin:13px 0}.card,.category-card,.change-card,.evidence-card{background:#0a1720;border:1px solid var(--line);border-radius:8px;padding:11px}.card strong,.change-card strong{display:block;color:var(--blue);font-size:20px}.category-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.category-card strong{display:block;font-size:17px;color:var(--accent)}.evidence-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:13px}.evidence-card strong{display:block;margin-bottom:5px;font-size:15px}.evidence-card p{margin:0;color:var(--muted);font-size:12px}.chip{display:inline-block;margin:2px 4px 2px 0;padding:3px 7px;border-radius:99px;background:#243f4d;font-size:11px}.chip.exposed{background:#34414a}.chip.inferred{background:#4a3d21;color:#ffe3a8}.chip.observed{background:#173f5c;color:#bce4ff}.chip.correlated{background:#174b3c;color:#bdf4dc}.chip.nonstandard{background:#512e54;color:#f1c8f3}.mac-note{display:inline-block;margin-top:3px;color:#9cd4ff;font-size:11px}.mac-note.indirect{color:#ffe3a8}.mac-note a{color:inherit}.provenance-icon{display:inline-flex;align-items:center;justify-content:center;width:16px;height:16px;margin-left:4px;border:1px solid currentColor;border-radius:50%;font-size:10px;font-weight:900}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:980px}th,td{text-align:left;vertical-align:top;padding:8px;border-bottom:1px solid var(--line);font-size:12px}th{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.04em}.host-row.hidden-row,.finding-row.hidden-row{display:none}.warning{padding:10px 12px;background:#2b2416;border:1px solid #8b692a;color:#ffe3a8;border-radius:8px;margin:8px 0}.changes{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:12px 0}.change-list{display:grid;grid-template-columns:1fr 1fr;gap:12px}.change-list section{background:#0a1720;border:1px solid var(--line);border-radius:9px;padding:12px}.change-list ul{margin:8px 0;padding-left:18px}.hidden{display:none!important}.footer{color:var(--muted);font-size:12px}details.panel>summary{cursor:pointer;font-size:16px;font-weight:750}details.panel[open]>summary{margin-bottom:14px}.scope-list{margin:8px 0 0;padding-left:18px;color:var(--muted)}@media(max-width:1320px){header,main{padding-left:4vw;padding-right:4vw}}@media(max-width:950px){.picker,.filters,.change-list{grid-template-columns:1fr}.cards,.category-grid,.changes,.evidence-grid{grid-template-columns:1fr 1fr}.overview{align-items:flex-start;flex-direction:column}}
</style></head><body>
<header><div class="eyebrow">Network-wide capability review</div><h1>Hunt</h1><p class="sub">Correlate the newest retained scan evidence across the network without executing anything.</p><nav class="nav" aria-label="Primary"><a href="/scans">Nmap</a><a href="/device-config">Device</a><a href="/analysis">Analyze</a><a class="active" href="/hunting" aria-current="page">Hunt</a><a href="/network-map">Map</a></nav></header>
<main>
<section class="panel overview"><div><h2 id="huntTitle">Latest network-wide evidence</h2><p id="huntSubtitle" class="meta">Loading the newest completed scan for each network scope…</p><div id="status" class="status" role="status"></div></div><div class="actions"><button id="refreshNetwork">Refresh network view</button><a class="source-links" href="/hunting">Reset to network-wide view</a></div></section>
<section id="huntPanel" class="hidden"><section class="panel"><div id="cards" class="cards"></div><div id="sources" class="source-links"></div><div id="scopeSummary"></div><div id="warnings"></div></section>
<section class="panel evidence-guide"><h2>Capability evidence guide</h2><p class="hint">These labels describe how NCT reached a capability classification. They do not, by themselves, prove a vulnerability or compromise.</p><div class="evidence-grid"><div class="evidence-card"><strong><span class="chip exposed">Exposed</span></strong><p>Nmap reported the port as open or open/filtered. Something is reachable, but NCT may not know what application is listening.</p></div><div class="evidence-card"><strong><span class="chip inferred">Inferred</span></strong><p>The port number is commonly associated with this capability. It is a useful lead, but applications can be moved to different ports.</p></div><div class="evidence-card"><strong><span class="chip observed">Observed</span></strong><p>Nmap identified a matching service or product fingerprint. This is stronger service evidence and can also identify services on unusual ports.</p></div><div class="evidence-card"><strong><span class="chip correlated">Correlated</span></strong><p>The conventional port and the observed fingerprint agree. This is NCT's strongest capability classification, but still requires analyst validation.</p></div></div></section>
<section class="panel"><h2>Capability categories</h2><div id="categories" class="category-grid"></div></section>
<section class="panel"><h2>Network filters</h2><p class="hint">Filters apply to both the host inventory and the capability findings below.</p><div class="filters"><div><label for="search">Host, service, product, version, or port</label><input id="search" type="search" placeholder="Try SSH, 443, Windows, or a hostname"></div><div><label for="osFilter">Operating system</label><select id="osFilter"><option value="">All operating systems</option></select></div><div><label for="subnetFilter">Subnet</label><select id="subnetFilter"><option value="">All subnets</option></select></div><div><label for="deviceTypeFilter">Device type</label><select id="deviceTypeFilter"><option value="">All device types</option></select></div><div><label for="category">Capability category</label><select id="category"><option value="">All categories</option></select></div><div><label for="capability">Capability evidence</label><select id="capability"><option value="">All evidence levels</option><option value="exposed">Exposed</option><option value="inferred">Inferred</option><option value="observed">Observed</option><option value="correlated">Correlated</option></select></div><div><label for="protocol">Protocol</label><select id="protocol"><option value="">All protocols</option><option value="tcp">TCP</option><option value="udp">UDP</option></select></div><label class="checkbox"><input id="nonstandard" type="checkbox"> Nonstandard ports only</label></div><p id="visibleCount" class="meta"></p></section>
<section class="panel"><h2>Host and device inventory</h2><p class="hint">Every observed host from the selected latest scans is retained here, including hosts with no matching capability finding.</p><div class="table-wrap"><table><thead><tr><th>Host / device</th><th>Subnet</th><th>Operating system</th><th>Device type</th><th>Capabilities</th><th>Latest evidence</th></tr></thead><tbody id="hostRows"></tbody></table></div></section>
<section class="panel"><h2>Capability findings</h2><div class="table-wrap"><table><thead><tr><th>Host</th><th>Subnet / device type</th><th>Category</th><th>Capability evidence</th><th>Port</th><th>Observed service</th><th>Match basis</th></tr></thead><tbody id="findingRows"></tbody></table></div></section></section>
<details class="panel"><summary>Focus on one scan or compare two scans</summary><p class="hint">The default view above is network-wide. Use this section when you need to isolate one retained scan or compare it with an older scan.</p><div class="picker"><div><label for="currentRun">Scan to review</label><select id="currentRun"><option value="">Loading completed scans…</option></select></div><div><label for="baselineRun">Optional comparison baseline</label><select id="baselineRun"><option value="">No comparison</option></select></div><button id="hunt">Open scan</button><button id="compare" class="secondary" disabled>Compare</button></div></details>
<section id="comparisonPanel" class="panel hidden"><h2>Hunting changes</h2><div id="comparison"></div></section><div class="footer">Build <code>{APP_VERSION}</code> · <code>{BUILD_ID}</code></div></main>
<script>
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let candidates=[],current=null;
const pageHeader=document.querySelector('header');function updateStickyOffset(){document.documentElement.style.setProperty('--hunt-header-offset',`${Math.ceil(pageHeader.getBoundingClientRect().height)+12}px`)}updateStickyOffset();new ResizeObserver(updateStickyOffset).observe(pageHeader);
function setStatus(message,kind=''){$('status').textContent=message;$('status').className='status '+kind}
function when(value){if(!value)return'—';const parsed=new Date(value);return Number.isNaN(parsed.valueOf())?value:parsed.toLocaleString()}
function label(item){return item.comparison_name||`${item.display_name||'Scan'} · ${when(item.completed_at||item.created_at)}`}
function optionRows(items){return items.map(item=>`<option value="${esc(item.selection_run_id)}">${esc(label(item))}</option>`).join('')}
function refreshBaselines(){const id=$('currentRun').value;$('baselineRun').innerHTML='<option value="">No comparison</option>'+optionRows(candidates.filter(item=>item.selection_run_id!==id));$('compare').disabled=!id||!$('baselineRun').value}
function stateChips(item){return(item.evidence_states||[]).map(state=>`<span class="chip ${esc(state)}">${esc(state)}</span>`).join('')+(item.nonstandard_port?'<span class="chip nonstandard">nonstandard port</span>':'')}
function sourceLinks(source){return(source?.evidence?.sources||[]).map(item=>`<a href="${esc(item.url)}" target="_blank" rel="noopener">${esc(item.label)}</a>`).join('')}
function macEvidence(item){if(!item.mac)return'<span class="meta">MAC not observed</span>';const p=item.mac_provenance||{},title=[p.origin,p.source_label,p.timestamp,p.detail].filter(Boolean).join(' · '),link=p.source_url?` · <a href="${esc(p.source_url)}" target="_blank" rel="noopener">source</a>`:'';return`<code>${esc(item.mac)}</code><br><span class="mac-note${p.indirect?' indirect':''}" title="${esc(title)}"><span class="provenance-icon">i</span> ${esc(p.indirect?'correlated by IP':'direct Nmap')}${link}</span>`}
function facetOptions(items,placeholder){return`<option value="">${esc(placeholder)}</option>`+(items||[]).map(item=>`<option value="${esc(item.name)}">${esc(item.name)} (${Number(item.host_count||0)})</option>`).join('')}
function rowData(item){const services=(item.services||[]).flatMap(value=>[value.port,value.protocol,value.service,value.product,value.version]),search=[item.ip,item.hostname,item.mac,item.vendor,item.os,item.os_group,item.os_filter,item.subnet,item.device_type,item.category,item.protocol,item.port,item.service,item.product,item.version,...services,...(item.categories||[]),...(item.match_basis||[])].join(' ').toLowerCase();return`data-search="${esc(search)}" data-os="${esc(item.os_filter||'Unclassified')}" data-subnet="${esc(item.subnet||'Unmapped')}" data-device="${esc(item.device_type||'Unclassified')}" data-category="${esc(item.category||(item.categories||[]).join('|'))}" data-protocol="${esc(item.protocol||(item.protocols||[]).join(' '))}" data-states="${esc((item.evidence_states||item.capability_states||[]).join(' '))}" data-nonstandard="${item.nonstandard_port?'yes':'no'}"`}
function renderHunt(data){current=data;$('huntPanel').classList.remove('hidden');const source=data.source||{},states=data.capability_states||{},facets=data.facets||{};$('huntTitle').textContent=source.display_name||'Hunt';$('huntSubtitle').textContent=source.comparison_name||when(source.completed_at||source.created_at);const cards=[['Observed hosts / devices',data.host_count],['Hosts with findings',data.hosts_with_findings_count],['Capability findings',data.finding_count],['Observed fingerprints',states.observed],['Correlated findings',states.correlated]];$('cards').innerHTML=cards.map(([name,value])=>`<div class="card"><strong>${Number(value||0)}</strong>${esc(name)}</div>`).join('');$('sources').innerHTML=sourceLinks(source);$('scopeSummary').innerHTML=(source.scope_summaries||[]).length?`<details><summary>Newest evidence selected from ${source.scope_summaries.length} network scope${source.scope_summaries.length===1?'':'s'}</summary><ul class="scope-list">${source.scope_summaries.map(item=>`<li>${esc(item.display_name||'Scan')} · ${esc((item.subnets||[]).join(', ')||'Unmapped scope')} · ${esc(when(item.completed_at))}</li>`).join('')}</ul></details>`:'';$('warnings').innerHTML=(data.warnings||[]).map(item=>`<div class="warning">${esc(item)}</div>`).join('');$('categories').innerHTML=(data.categories||[]).map(item=>`<div class="category-card"><strong>${item.finding_count}</strong>${esc(item.name)}</div>`).join('')||'<p class="empty">No categorized open services were found.</p>';$('category').innerHTML='<option value="">All categories</option>'+(data.categories||[]).map(item=>`<option value="${esc(item.name)}">${esc(item.name)}</option>`).join('');$('osFilter').innerHTML=facetOptions(facets.operating_systems,'All operating systems');$('subnetFilter').innerHTML=facetOptions(facets.subnets,'All subnets');$('deviceTypeFilter').innerHTML=facetOptions(facets.device_types,'All device types');$('hostRows').innerHTML=(data.hosts||[]).map(item=>`<tr class="host-row" ${rowData(item)}><td><strong>${esc(item.ip||item.hostname||'—')}</strong><br><span class="meta">${esc(item.hostname||'')}</span><br>${macEvidence(item)}</td><td><code>${esc(item.subnet||'Unmapped')}</code></td><td>${esc(item.os||item.os_group||'Unclassified')}<br><span class="meta">${esc(item.vendor||'')}</span></td><td>${esc(item.device_type||'Unclassified')}</td><td>${(item.categories||[]).map(value=>`<span class="chip">${esc(value)}</span>`).join('')||'<span class="meta">No matching services</span>'}</td><td>${esc(when(item.last_observed))}<br>${sourceLinks({evidence:{sources:item.source_refs||[]}})}</td></tr>`).join('');$('findingRows').innerHTML=(data.findings||[]).map(item=>`<tr class="finding-row" ${rowData(item)}><td><strong>${esc(item.ip||item.hostname||'—')}</strong><br><span class="meta">${esc(item.hostname||item.os_group||'')}</span><br>${macEvidence(item)}</td><td><code>${esc(item.subnet||'Unmapped')}</code><br><span class="meta">${esc(item.device_type||'Unclassified')}</span></td><td>${esc(item.category)}</td><td>${stateChips(item)}</td><td><code>${esc(item.port)}/${esc(item.protocol)}</code>${item.outlier?'<br><span class="chip inferred">outlier</span>':''}</td><td>${esc(item.service||'unknown')}<br><span class="meta">${esc([item.product,item.version].filter(Boolean).join(' ')||'No product fingerprint')}</span></td><td>${(item.match_basis||[]).map(esc).join('<br>')}</td></tr>`).join('');applyFilters()}
function matches(row,isHost){const term=$('search').value.trim().toLowerCase(),os=$('osFilter').value,subnet=$('subnetFilter').value,device=$('deviceTypeFilter').value,category=$('category').value,protocol=$('protocol').value,state=$('capability').value,nonstandard=$('nonstandard').checked;const categoryMatch=!category||(isHost?row.dataset.category.split('|').includes(category):row.dataset.category===category),protocolMatch=!protocol||(isHost?row.dataset.protocol.split(' ').includes(protocol):row.dataset.protocol===protocol);return(!term||row.dataset.search.includes(term))&&(!os||row.dataset.os===os)&&(!subnet||row.dataset.subnet===subnet)&&(!device||row.dataset.device===device)&&categoryMatch&&protocolMatch&&(!state||row.dataset.states.split(' ').includes(state))&&(!nonstandard||row.dataset.nonstandard==='yes')}
function applyFilters(){if(!current)return;let hosts=0,findings=0;document.querySelectorAll('.host-row').forEach(row=>{const show=matches(row,true);row.classList.toggle('hidden-row',!show);if(show)hosts++});document.querySelectorAll('.finding-row').forEach(row=>{const show=matches(row,false);row.classList.toggle('hidden-row',!show);if(show)findings++});$('visibleCount').textContent=`${hosts} of ${current.host_count||0} hosts / devices and ${findings} of ${current.finding_count||0} capability findings shown.`}
async function loadNetwork(){setStatus('Correlating the newest retained scans across the network…');try{const response=await fetch('/api/hunting/network'),data=await response.json();if(!response.ok)throw new Error(data.detail||'Network hunting view failed');renderHunt(data);setStatus('Network-wide hunting view is current.','good');history.replaceState(null,'','/hunting')}catch(error){setStatus(error.message,'bad')}}
async function hunt(){const id=$('currentRun').value;if(!id){setStatus('Choose a completed scan first.','warn');return}setStatus('Opening the selected scan…');try{const response=await fetch(`/api/hunting/${encodeURIComponent(id)}`),data=await response.json();if(!response.ok)throw new Error(data.detail||'Hunting analysis failed');renderHunt(data);setStatus('Focused scan view is current.','good');history.replaceState(null,'',`/hunting?run=${encodeURIComponent(id)}`)}catch(error){setStatus(error.message,'bad')}}
function findingText(item){return`${item.ip||item.hostname||'host'} · ${item.category} · ${item.port}/${item.protocol} ${item.service||''}`}
function list(title,items,render){return`<section><h3>${esc(title)} <span class="chip">${items.length}</span></h3>${items.length?`<ul>${items.map(item=>`<li>${esc(render(item))}</li>`).join('')}</ul>`:'<p class="empty">None</p>'}</section>`}
async function compare(){const before=$('baselineRun').value,after=$('currentRun').value;if(!before||!after)return;setStatus('Comparing hunting evidence…');try{const response=await fetch(`/api/hunting/compare?before=${encodeURIComponent(before)}&after=${encodeURIComponent(after)}`),data=await response.json();if(!response.ok)throw new Error(data.detail||'Hunting comparison failed');const s=data.summary||{};$('comparisonPanel').classList.remove('hidden');const coverage=(data.coverage_warnings||[]).map(item=>`<div class="warning">${esc(item)}</div>`).join('');$('comparison').innerHTML=`${coverage}<p class="meta">${esc(data.before?.comparison_name||'Baseline')} → ${esc(data.after?.comparison_name||'Current')}</p><div class="changes">${Object.entries(s).map(([name,value])=>`<div class="change-card"><strong>${value}</strong>${esc(name.replaceAll('_',' '))}</div>`).join('')}</div><div class="change-list">${list('Findings added',data.findings_added||[],findingText)}${list('Findings removed',data.findings_removed||[],findingText)}${list('Findings changed',data.findings_changed||[],item=>`${findingText(item.finding)} · ${Object.keys(item.changes).join(', ')}`)}${list('Host category changes',data.host_category_changes||[],item=>`${item.host_key} · added: ${item.categories_added.join(', ')||'—'} · removed: ${item.categories_removed.join(', ')||'—'}`)}</div>`;setStatus('Hunting comparison complete.','good');$('comparisonPanel').scrollIntoView({behavior:'smooth',block:'start'})}catch(error){setStatus(error.message,'bad')}}
async function loadCandidates(){try{const response=await fetch('/api/scan-comparisons/candidates'),data=await response.json();if(!response.ok)throw new Error(data.detail||'Completed scans unavailable');candidates=data;$('currentRun').innerHTML='<option value="">Choose a completed scan…</option>'+optionRows(candidates);const requested=new URLSearchParams(location.search).get('run');if(requested&&candidates.some(item=>item.selection_run_id===requested))$('currentRun').value=requested;refreshBaselines()}catch(error){setStatus(error.message,'bad')}}
async function start(){const requested=new URLSearchParams(location.search).get('run');loadCandidates();if(requested){await fetch(`/api/hunting/${encodeURIComponent(requested)}`).then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.detail||'Hunting analysis failed');renderHunt(data);setStatus('Focused scan view is current.','good')}).catch(error=>setStatus(error.message,'bad'))}else await loadNetwork()}
$('currentRun').onchange=refreshBaselines;$('baselineRun').onchange=()=>{$('compare').disabled=!$('baselineRun').value||!$('currentRun').value};$('hunt').onclick=hunt;$('compare').onclick=compare;$('refreshNetwork').onclick=loadNetwork;for(const id of['search','osFilter','subnetFilter','deviceTypeFilter','category','protocol','capability','nonstandard'])$(id).addEventListener(id==='search'?'input':'change',applyFilters);start();
</script></body></html>'''
    return HTMLResponse(
        html.replace("{APP_VERSION}", APP_VERSION).replace("{BUILD_ID}", BUILD_ID)
    )
